const bubbles=[];for(let i=0;i<11;i++){const b=new THREE.Mesh(new THREE.IcosahedronGeometry(.08+(i%3)*.035,1),new THREE.MeshStandardMaterial({color:'#e4fff0',transparent:true,opacity:.38,roughness:.2}));b.position.set(Math.sin(i*7)*7,-.35,Math.cos(i*4)*6);scene.add(b);bubbles.push(b)}
let last=performance.now(),saveTick=0,elapsed=0;
